#include <iostream>
#include <set>
using namespace std;

int main() {
    int n = 0;
    cin >> n;

    set<int> s;
    for (int i = 0; i < n; i++) {
        int x = 0;
        cin >> x;
        s.insert(x);
    }

    for (int x : s) {
        cout << x << endl;
    }
    cout << s.size() << endl;
    return 0;
}
